INSERT INTO "discrepancies" VALUES(1,'"Welcome to Disney Land" sign: book Ch.36 says it''s from Scott''s mother, rediscovered near the stairs. Journal says Adrianna drew it, signed "Mom," hanging in Fantasyland.','book Ch.36; journal lines 16707-17003','open');
INSERT INTO "discrepancies" VALUES(2,'Two home addresses used for "Heaven on Earth": 8830 Longbow Place (used almost everywhere) vs. 4700 Marlin Court (used once).','journal line 32170 vs. lines 206-244 etc.','open');
INSERT INTO "discrepancies" VALUES(3,'Name variant: "Scott William Wilson" appears once, vs. "Scott Christopher Wilson" used everywhere else including his own name-decode sections.','journal lines 30446, 30489','open');
INSERT INTO "discrepancies" VALUES(4,'Spelling variant: "Jeffery David Wilson" (early range) vs. "Jeffrey David Wilson" (later range) for the same brother.','journal line 3169 vs. lines 30442-30487','open');
INSERT INTO "discrepancies" VALUES(5,'Two people named Helen: the mother (Helen Paulette Bort, nickname "MIA") and a grandmother (nickname "MIMI," born Dec 16) — journal is not fully consistent about which is which.','journal lines 30420-30506, 33989-34898','open');
INSERT INTO "discrepancies" VALUES(6,'Internal contradiction in the source document itself: ZIM/BIM assigned 1=light/0=dark at one point, reversed at another.','journal line 14538 vs. line 16239','open (source document''s own inconsistency, not an extraction error)');
